# 1. Transform values
nums = {"a": 1, "b": 2, "c": 3}
squared = {k: v**2 for k, v in nums.items()}
print(squared)       # {'a': 1, 'b': 4, 'c': 9}

# 2. Filter entries
passing = {k: v for k, v in nums.items() if v > 1}
print(passing)       # {'b': 2, 'c': 3}

# 3. Invert: value -> key (assumes unique values)
orig = {"a": 1, "b": 2, "c": 3}
inv  = {v: k for k, v in orig.items()}
print(inv)           # {1: 'a', 2: 'b', 3: 'c'}

# 4. From two lists (zip)
keys   = ["name", "age", "city"]
values = ["Alice",  25,  "Delhi"]
d = {k: v for k, v in zip(keys, values)}
print(d)   # {'name': 'Alice', 'age': 25, 'city': 'Delhi'}

# 5. Character frequency
text = "abracadabra"
freq = {ch: text.count(ch) for ch in set(text)}
print(freq)   # {'r':2,'c':1,'a':5,'d':1,'b':2}

# 6. Conditional key transformation
words = ["hello", "WORLD", "Python", "GATE"]
normalised = {w.lower(): len(w) for w in words}
print(normalised)  # {'hello':5,'world':5,'python':6,'gate':4}

# 7. Nested dict comprehension
matrix = [[1,2,3],[4,5,6],[7,8,9]]
indexed = {(i,j): matrix[i][j]
           for i in range(3) for j in range(3)}
print(indexed[(1,2)])   # 6

# 8. Duplicate key: last wins
data = [("a",1),("b",2),("a",3),("b",4)]
d2 = {k: v for k, v in data}
print(d2)   # {'a': 3, 'b': 4}  (last 'a' and 'b' values win)

# 1. Unique squares
sq = {x**2 for x in range(-4, 5)}
print(sorted(sq))    # [0, 1, 4, 9, 16]  (deduped: (-2)^2 == 2^2)

# 2. Unique first letters
words = ["apple","ant","banana","blueberry","avocado"]
initials = {w[0] for w in words}
print(initials)      # {'a', 'b'}

# 3. Common elements (set comprehension on two lists)
a = [1,2,3,4,5,3,2]
b = [3,4,5,6,7,4,3]
common = {x for x in a if x in b}
print(common)        # {3, 4, 5}

# 4. Characters appearing in both strings
s1, s2 = "abcde", "cdefg"
shared = {c for c in s1 if c in s2}
print(shared)        # {'c', 'd', 'e'}

# 5. Deduplication with transformation
data = [3, -3, 1, -1, 2, -2, 1]
unique_abs = {abs(x) for x in data}
print(unique_abs)    # {1, 2, 3}

